        best_dist = None
        target = None
        for r in resources:
            rx, ry = r[0], r[1]
            d = abs(rx - x) + abs(ry - y)
            if best_dist is None or d < best_dist:
                best_dist = d
                target = (rx, ry)
        if target is not None:
            tx, ty = target
            if tx > x:
                best_dx = 1
            elif tx < x:
                best_dx = -1
            if ty > y:
                best_dy = 1
            elif ty < y:
                best_dy = -1
            return [best_dx, best_dy]

    # If no resources, try to move toward center if map known
    grid_w = observation.get("grid_width", None)
    grid_h = observation.get("grid_height", None)
    if grid_w is not None and grid_h is not None:
        cx = grid_w // 2
        cy = grid_h // 2
        if cx > x:
            best_dx = 1
        elif cx < x:
            best_dx = -1
        if cy > y:
            best_dy = 1
        elif cy < y:
            best_dy = -1
        return [best_dx, best_dy]

    # Fallback: stay
    return [0, 0]

